function mergeState(source) {
  const next = structuredClone(seed);
  Object.keys(seed).forEach(key => {
    if (Array.isArray(seed[key])) { if (Array.isArray(source?.[key])) next[key] = source[key]; }
    else if (source?.[key] !== undefined) next[key] = source[key];
  });
  if (Number(source?.schemaVersion || 0) < 3) {
    ['administrador', 'financeiro'].forEach(id => {
      const profile = next.profiles.find(item => item.id === id);
      if (profile) profile.permissions = [...new Set([...(profile.permissions || []), 'cashflow'])];
    });
  }
  next.schemaVersion = 3;
  return next;
}
function loadState() {
  try { const stored = JSON.parse(localStorage.getItem(storageKey)); return stored ? mergeState(stored) : structuredClone(seed); } catch { return structuredClone(seed); }
}
function profileFor(user = currentUser) { return state.profiles?.find(profile => profile.id === user?.profileId) || state.profiles?.find(profile => profile.id === 'administrador'); }
function canAccess(moduleId) { return moduleId === 'summary' || Boolean(profileFor()?.permissions?.includes(moduleId)); }
function accessibleModules() { return moduleDefs.filter(item => canAccess(item.id)); }
function updateCurrentUserUi() { const profile = profileFor(); const name = currentUser?.name || 'Visitante'; const initials = name.split(/\s+/).filter(Boolean).slice(0, 2).map(part => part[0]).join('').toUpperCase(); if (byId('currentAccessBadge')) byId('currentAccessBadge').textContent = profile ? `Perfil · ${profile.name}` : 'Acesso'; if (byId('currentUserName')) byId('currentUserName').textContent = name; if (byId('currentUserRole')) byId('currentUserRole').textContent = profile?.name || 'Sem perfil'; if (byId('currentUserAvatar')) byId('currentUserAvatar').textContent = initials || 'AM'; }
function persist() { localStorage.setItem(storageKey, JSON.stringify(state)); updateSync(); if (apiToken) { syncQueue = syncQueue.then(() => syncServerState()).catch(() => {}); } }
function updateSync() { const now = new Date(); const t = `Atualizado ${now.toLocaleTimeString('pt-AO', { hour: '2-digit', minute: '2-digit' })}`; if (byId('lastSync')) byId('lastSync').textContent = t; if (byId('footerSync')) byId('footerSync').textContent = `${now.toLocaleDateString('pt-AO', { day: '2-digit', month: 'short', year: 'numeric' })}, ${t.replace('Atualizado ', '')}`; }
function toast(message) { const el = byId('toast'); el.textContent = message; el.classList.add('show'); window.clearTimeout(toast.timer); toast.timer = window.setTimeout(() => el.classList.remove('show'), 3600); }
function showLogin(message = '') { currentUser = null; byId('appShell').hidden = true; byId('loginScreen').hidden = false; byId('loginError').textContent = message; window.setTimeout(() => byId('loginUsername')?.focus(), 0); }
function showApp() { byId('loginScreen').hidden = true; byId('appShell').hidden = false; updateCurrentUserUi(); renderAll(); }
function applyServerState(remoteState) { state = mergeState(remoteState || {}); localStorage.setItem(storageKey, JSON.stringify(state)); }
async function remoteRequest(path, options = {}) { const headers = { 'Content-Type': 'application/json', ...(options.headers || {}) }; if (apiToken) headers.Authorization = `Bearer ${apiToken}`; const response = await fetch(`${apiBase}${path}`, { ...options, headers }); const payload = await response.json().catch(() => ({})); if (!response.ok) { const error = new Error(payload.error || 'Serviço remoto indisponível.'); error.status = response.status; throw error; } return payload; }
async function restoreRemoteSession() { if (!apiToken) return false; try { const payload = await remoteRequest('/api/auth/me'); applyServerState(payload.state); currentUser = payload.user; remoteMode = true; localStorage.setItem(sessionKey, JSON.stringify({ id: currentUser.id })); return true; } catch { apiToken = ''; localStorage.removeItem(apiTokenKey); return false; } }
async function loginRemote(username, password) { try { const response = await fetch(`${apiBase}/api/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username, password, bootstrapState: state }) }); const payload = await response.json().catch(() => ({})); if (response.status === 503) return null; if (!response.ok) return { error: payload.error || 'Usuário ou senha inválidos.' }; apiToken = payload.token; remoteMode = true; localStorage.setItem(apiTokenKey, apiToken); applyServerState(payload.state); currentUser = payload.user; localStorage.setItem(sessionKey, JSON.stringify({ id: currentUser.id })); return true; } catch { return null; } }
async function syncServerState() { if (!apiToken) return; try { const payload = await remoteRequest('/api/state', { method: 'PUT', body: JSON.stringify({ state }) }); applyServerState(payload.state); currentUser = payload.user; remoteMode = true; } catch (error) { if (error.status === 401) { apiToken = ''; localStorage.removeItem(apiTokenKey); remoteMode = false; } } }
function bindAuth() { byId('loginForm')?.addEventListener('submit', async event => { event.preventDefault(); const loginForm = event.currentTarget; const submit = loginForm.querySelector('button[type="submit"]'); if (submit) { submit.disabled = true; submit.textContent = 'A entrar…'; } const form = new FormData(loginForm); const username = String(form.get('username') || '').trim().toLowerCase(); const password = String(form.get('password') || ''); const remoteResult = await loginRemote(username, password); if (remoteResult === true) { loginForm.reset(); showApp(); } else if (remoteResult?.error) { byId('loginError').textContent = remoteResult.error; } else { const user = state.users.find(item => item.active && (item.username.toLowerCase() === username || String(item.email || '').trim().toLowerCase() === username) && item.password === password); if (!user) byId('loginError').textContent = 'Usuário ou senha inválidos.'; else { currentUser = user; localStorage.setItem(sessionKey, JSON.stringify({ id: user.id })); loginForm.reset(); showApp(); } } if (submit) { submit.disabled = false; submit.textContent = 'Entrar'; } }); byId('logoutButton')?.addEventListener('click', () => { localStorage.removeItem(sessionKey); localStorage.removeItem(apiTokenKey); apiToken = ''; remoteMode = false; showLogin(); }); showLogin(); restoreRemoteSession().then(restored => { if (restored) showApp(); else { const savedSession = localStorage.getItem(sessionKey); if (savedSession) { try { const saved = JSON.parse(savedSession); currentUser = state.users.find(user => user.id === saved.id && user.active) || null; } catch { currentUser = null; } } if (currentUser) showApp(); } }); }
function defFor(id) { return moduleDefs.find(item => item.id === id); }
function renderNav() { byId('moduleNav').innerHTML = `<ul class="nav-list">${accessibleModules().map(item => `<li><button class="nav-item ${item.id === 'summary' ? 'active' : ''}" data-module-target="${item.id}"><span class="nav-icon">${item.icon}</span><span>${item.label}</span>${item.id === 'accounting' ? `<span class="nav-badge" id="expenseBadge">${state.expenses.length}</span>` : ''}</button></li>`).join('')}</ul>`; document.querySelectorAll('[data-module-target]').forEach(btn => btn.addEventListener('click', () => switchModule(btn.dataset.moduleTarget))); updateCurrentUserUi(); }
function switchModule(id) { const item = defFor(id) || defFor('summary'); if (!canAccess(item.id)) { toast('Seu perfil não tem acesso a este módulo.'); return switchModule('summary'); } const isSummary = item.id === 'summary'; byId('view-dashboard').classList.toggle('active', isSummary); byId('view-module').classList.toggle('active', !isSummary); document.querySelectorAll('.nav-item').forEach(btn => btn.classList.toggle('active', btn.dataset.moduleTarget === item.id)); byId('pageTitle').textContent = item.label; if (!isSummary) renderModule(item.id); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function renderAll() { renderNav(); renderSummary(); const active = document.querySelector('.nav-item.active')?.dataset.moduleTarget || 'summary'; if (active !== 'summary' && canAccess(active)) renderModule(active); }

function totals() { const expenses = state.expenses.reduce((sum, row) => sum + Number(row.amount || 0), 0); const maintenance = state.maintenance.filter(row => ['Paga', 'Executada'].includes(row.status)).reduce((sum, row) => sum + Number(row.planned || 0), 0); const paid = state.paymentRegister.reduce((sum, row) => sum + Number(row.amount || 0), 0); const pendingChanges = state.changes.filter(row => row.status === 'Pendente').length; const pendingPurchases = state.purchases.filter(row => row.status !== 'Paga').length; return { expenses, maintenance, paid, pendingChanges, pendingPurchases, realized: expenses + maintenance, balance: Math.max(0, state.budget.total - paid - expenses - maintenance) }; }
function renderSummary() { renderEnhancedSummary(); }
function renderBars() { const max = Math.max(...state.budget.categories.map(item => Number(item.expected)), 1); const realized = totals().realized; byId('budgetBars').innerHTML = state.budget.categories.map((item, index) => { const actual = index === 2 ? state.expenses.filter(x => x.type === 'Combustível').reduce((s, x) => s + Number(x.amount || 0), 0) : index === 3 ? totals().maintenance : 0; return `<div class="bar-row"><span class="bar-label">${esc(item.label)}</span><div class="bars"><span class="bar-track"><i class="bar expected" style="width:${Math.max(1, Number(item.expected) / max * 100)}%"></i></span><span class="bar-track"><i class="bar actual" style="width:${actual ? Math.min(100, actual / max * 100) : 0}%"></i></span></div><span class="bar-value">${money(item.expected)}</span></div>`; }).join(''); void realized; }
function renderTeams() { byId('teamList').innerHTML = state.teams.map(team => `<div class="team-item"><div class="team-avatar ${team.color === 'coral' ? 'coral' : ''}">${esc(team.id)}</div><div class="team-main"><strong>${esc(team.mission)}</strong><span>${team.people || '—'} titulares · ${Number(team.km || 0).toLocaleString('pt-AO')} km rodoviários</span></div><div class="team-side"><div class="team-status ${team.status === 'Aprovada' ? 'green' : 'gold'}">${esc(team.status)}</div><div class="team-dates">${team.vehicle || 'Sem viatura'} · ${money(team.total || 0)}</div></div></div>`).join(''); }
function renderLatestExpenses() { byId('latestExpenses').innerHTML = state.expenses.slice().reverse().map(item => `<tr><td><strong>${esc(item.team)}</strong></td><td>${shortDate(item.date)}</td><td>${esc(item.type)}</td><td>${esc(item.supplier || '—')}</td><td class="align-right"><strong>${money(item.amount)}</strong></td></tr>`).join('') || '<tr><td colspan="5">Nenhuma despesa lançada.</td></tr>'; }
function renderAttention() { const rows = []; const pendingChange = state.changes.find(row => row.status === 'Pendente'); if (pendingChange) rows.push(['gold', 'Alteração pendente', `${pendingChange.id} · ${pendingChange.type} · ${pendingChange.team}`, 'changes']); const pendingPurchase = state.purchases.find(row => row.status === 'Aguardando aprovação'); if (pendingPurchase) rows.push(['coral', 'Compra extra aguardando aprovação', `${pendingPurchase.id} · ${pendingPurchase.item}`, 'purchases']); const overdue = state.fleet.find(row => row.status !== 'Em dia'); if (overdue) rows.push(['blue', 'Leitura de frota atrasada', `${overdue.vehicle} · atualize a quilometragem`, 'fleet']); const missing = state.bank.filter(row => row.status !== 'Validada').length; if (missing) rows.push(['blue', `${missing} beneficiário sem conta validada`, 'Complete Dados Bancários antes do pagamento.', 'bank']); byId('alertCount').textContent = rows.length; byId('attentionList').innerHTML = rows.map(row => `<button class="attention-item attention-link" data-module-target="${row[3]}"><span class="attention-icon ${row[0]}">!</span><div><strong>${esc(row[1])}</strong><span>${esc(row[2])}</span></div><span class="arrow">→</span></button>`).join('') || '<div class="empty-state">Nenhuma pendência crítica no momento.</div>'; byId('attentionList').querySelectorAll('[data-module-target]').forEach(btn => btn.addEventListener('click', () => switchModule(btn.dataset.moduleTarget))); }
function renderShortcuts() { byId('moduleShortcuts').innerHTML = accessibleModules().filter(item => item.id !== 'summary').map(item => `<button class="module-shortcut" data-module-target="${item.id}"><span class="shortcut-icon">${item.icon}</span><span><strong>${item.label}</strong><small>${item.kind === 'help' ? 'Fluxo e regras' : item.kind === 'reports' ? 'PDF e Excel' : item.kind === 'cashflow' ? 'Previsão financeira por etapas' : item.kind === 'access' ? 'Usuários e permissões' : 'Abrir módulo'}</small></span><span class="arrow">→</span></button>`).join(''); byId('moduleShortcuts').querySelectorAll('[data-module-target]').forEach(btn => btn.addEventListener('click', () => switchModule(btn.dataset.moduleTarget))); }

function renderModule(id) { if (id === 'instructions') return renderHelp(); if (id === 'cashflow') return renderCashFlow(); if (id === 'reports') return renderReports(); if (id === 'accounting') return renderAccounting(); if (id === 'access') return renderAccessControl(); return renderGeneric(id); }
function moduleHeader(def, actionText = 'Novo registo') { return `<div class="page-heading compact-heading"><div><div class="kicker">MÓDULO ADMINISTRATIVO</div><h1>${def.label}</h1><p>${specs[def.id]?.description || 'Área de trabalho do controlo financeiro PEMx-RNA.'}</p></div><div class="heading-actions"><button class="button secondary" id="moduleExport"><span>↓</span> Exportar módulo</button><button class="button primary" data-scroll-form="true"><span>＋</span> ${actionText}</button></div></div>`; }
function renderHelp() { byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">MÓDULO ADMINISTRATIVO</div><h1>Instruções / Ajuda</h1><p>O fluxo da planilha foi organizado em módulos para uso do administrador.</p></div><span class="admin-badge">Base PEMx-RNA</span></div><div class="help-grid"><article class="panel help-intro"><div class="panel-heading"><div><h2>Como usar o sistema</h2><p>Comece no Resumo e avance pelos módulos na ordem da operação.</p></div><span class="file-icon">?</span></div><div class="help-steps">${['Cadastre parâmetros, funcionários e equipes antes de montar as rotas.', 'Componha cada equipe e defina titulares, reservas e viatura.', 'Lance as rotas por etapas. Cabinda deve ser tratada como deslocamento aéreo.', 'Registe alterações. Apenas uma alteração aprovada atualiza o planeamento.', 'Lance passagens, manutenção, quilometragem e compras extras nos respetivos módulos.', 'Valide dados bancários, registre pagamentos e acompanhe o a pagar.', 'Use Prestação de Contas para combustível e despesas pagas pelo adiantamento.', 'Exporte o relatório completo em PDF ou Excel para o administrador e para a direção.'].map((text, i) => `<div class="help-step"><span>${i + 1}</span><p>${text}</p></div>`).join('')}</div></article><article class="panel rules-panel"><div class="panel-heading"><div><h2>Regras principais</h2><p>Conforme a aba Instruções da planilha de referência.</p></div></div><div class="rule-list"><div><strong>Diárias</strong><span>América: 40 000 Kz/noite. África: 40 000 Kz/noite + 10 000 Kz/dia.</span></div><div><strong>Contingências</strong><span>Reservas só são pagas quando ativadas. Contingência financeira fica separada.</span></div><div><strong>Prestação</strong><span>Combustível e outras despesas entram no acerto. Passagens são pagas diretamente pela empresa.</span></div><div><strong>Segurança</strong><span>Dados bancários ficam restritos ao modo administrador e aparecem mascarados nas tabelas.</span></div></div></article></div>`; }

function renderAccessControlLegacy() { if (currentUser?.profileId !== 'administrador') { toast('Somente o administrador pode gerir perfis e acessos.'); return switchModule('summary'); } const managedModules = moduleDefs.filter(item => item.id !== 'summary'); const profileRows = state.profiles.map(profile => `<tr><th><strong>${esc(profile.name)}</strong><small>${esc(profile.description)}</small></th>${managedModules.map(item => `<td><label class="permission-toggle"><input type="checkbox" data-profile-id="${esc(profile.id)}" data-permission="${esc(item.id)}" ${profile.permissions.includes(item.id) ? 'checked' : ''} ${profile.id === 'administrador' && item.id === 'access' ? 'disabled' : ''} /><span>${profile.permissions.includes(item.id) ? '✓' : '—'}</span></label></td>`).join('')}</tr>`).join(''); const userRows = state.users.map(user => `<tr><td><strong>${esc(user.name)}</strong><small>${esc(user.username)} · ${user.active ? 'Ativo' : 'Inativo'}</small></td><td><select class="user-profile-select" data-user-id="${esc(user.id)}">${state.profiles.map(profile => `<option value="${esc(profile.id)}" ${profile.id === user.profileId ? 'selected' : ''}>${esc(profile.name)}</option>`).join('')}</select></td><td><span class="status-chip ${user.active ? '' : 'warning-chip'}">${user.active ? 'Ativo' : 'Inativo'}</span></td><td><button class="mini-action danger-action" data-user-action="delete" data-user-id="${esc(user.id)}" ${user.id === currentUser.id ? 'disabled' : ''}>Excluir</button></td></tr>`).join(''); byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">ADMINISTRADOR</div><h1>Perfis e acessos</h1><p>Defina o que cada perfil pode abrir e associe cada usuário ao seu perfil.</p></div><span class="admin-badge">${state.users.length} usuários</span></div><div class="access-layout"><article class="panel access-panel"><div class="panel-heading"><div><h2>Matriz de permissões</h2><p>Marque os módulos permitidos para cada perfil.</p></div><span class="panel-tag">Editável</span></div><div class="access-matrix-scroll"><table class="access-matrix"><thead><tr><th>Perfil</th>${managedModules.map(item => `<th title="${esc(item.label)}">${item.icon}<span>${esc(item.label)}</span></th>`).join('')}</tr></thead><tbody>${profileRows}</tbody></table></div></article><article class="panel access-users-panel"><div class="panel-heading"><div><h2>Usuários e perfis</h2><p>Altere a função de acesso de cada usuário.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Usuário</th><th>Perfil</th><th>Estado</th><th>Ações</th></tr></thead><tbody>${userRows || '<tr><td colspan="4">Nenhum usuário cadastrado.</td></tr>'}</tbody></table></div><form class="access-user-form" id="accessUserForm"><h3>Adicionar usuário</h3><div class="form-row two"><label>Nome<input name="name" required placeholder="Nome completo" /></label><label>Login<input name="username" required placeholder="usuario" /></label></div><div class="form-row two"><label>Senha inicial<input name="password" required type="password" placeholder="Senha" /></label><label>Perfil<select name="profileId">${state.profiles.map(profile => `<option value="${esc(profile.id)}">${esc(profile.name)}</option>`).join('')}</select></label></div><button class="button primary" type="submit">＋ Criar usuário</button></form></article></div>`; bindAccessControl(); }
function bindAccessControlLegacy() { byId('moduleHost').querySelectorAll('[data-profile-id]').forEach(input => input.addEventListener('change', () => { const profile = state.profiles.find(item => item.id === input.dataset.profileId); if (!profile) return; if (input.dataset.permission === 'access' && profile.id === 'administrador') { input.checked = true; return; } profile.permissions = input.checked ? [...new Set([...profile.permissions, input.dataset.permission])] : profile.permissions.filter(permission => permission !== input.dataset.permission); persist(); input.nextElementSibling.textContent = input.checked ? '✓' : '—'; toast(`Permissão de ${profile.name} atualizada.`); })); byId('moduleHost').querySelectorAll('.user-profile-select').forEach(select => select.addEventListener('change', () => { const user = state.users.find(item => item.id === select.dataset.userId); if (!user) return; user.profileId = select.value; persist(); if (user.id === currentUser.id) updateCurrentUserUi(); toast(`Perfil de ${user.name} atualizado.`); })); byId('moduleHost').querySelectorAll('[data-user-action="delete"]').forEach(button => button.addEventListener('click', () => { const user = state.users.find(item => item.id === button.dataset.userId); if (!user || user.id === currentUser.id || !window.confirm(`Excluir o usuário ${user.name}?`)) return; state.users = state.users.filter(item => item.id !== user.id); persist(); renderAccessControl(); toast('Usuário excluído.'); })); byId('accessUserForm')?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget).entries()); if (state.users.some(user => user.username.toLowerCase() === String(data.username).trim().toLowerCase())) return toast('Este login já está cadastrado.'); state.users.push({ id: `USR-${String(Date.now()).slice(-5)}`, name: String(data.name).trim(), username: String(data.username).trim(), password: String(data.password), profileId: data.profileId, active: true }); persist(); renderAccessControl(); toast('Usuário criado.'); }); }
function rowsFor(id) { const spec = specs[id]; return state[defFor(id)?.stateKey || id] || []; }
function cellValue(value, key) { if (value === undefined || value === null || value === '') return '—'; if (['amount', 'due', 'paid', 'balance', 'planned', 'impact', 'estimated', 'total'].includes(key)) return money(value); if (key === 'valueUsd') return `${Number(value || 0).toLocaleString('pt-AO')} USD`; if (['date', 'departure', 'lastReading', 'nextService'].includes(key)) return shortDate(value); return String(value); }
function genericField(id, field) { if (id === 'composition' && field[0] === 'team') return `<label>${field[1]}<select name="team">${state.teams.map(team => `<option value="${esc(team.id)}">${esc(team.id)} · ${esc(team.mission)}</option>`).join('')}</select></label>`; if (id === 'composition' && field[0] === 'employee') return '<label>Funcionários (um por linha)<textarea name="employee" rows="4" required placeholder="Digite ou cole um nome por linha"></textarea><small class="field-hint">Cada nome cria um membro separado na equipe selecionada. Separe por linhas ou ponto e vírgula.</small></label>'; if (id === 'composition' && field[0] === 'paper') return `<label>${field[1]}<select name="paper"><option>Titular</option><option>Reserva</option></select></label>`; return `<label>${field[1]}<input name="${field[0]}" type="${field[2]}" ${field[2] === 'number' ? 'inputmode="decimal"' : ''} /></label>`; }
function renderGeneric(id) { const def = defFor(id); const spec = specs[id]; const rows = rowsFor(id); const isComposition = id === 'composition'; const isDistance = id === 'distances'; byId('moduleHost').innerHTML = `${moduleHeader(def, isComposition ? 'Adicionar membro' : isDistance ? 'Calcular distância' : 'Novo registo')}<div class="module-layout"><article class="panel module-table"><div class="panel-heading"><div><h2>${isComposition ? 'Membros das equipes' : isDistance ? 'Percursos calculados' : 'Registos'}</h2><p>${rows.length} registos disponíveis neste ambiente.</p></div><span class="panel-tag">Interativo</span></div>${id === 'parameters' ? '<p class="inline-edit-hint">Os valores podem ser editados diretamente na tabela. Pressione Tab ou clique fora do campo para guardar.</p>' : ''}${isComposition ? '<p class="inline-edit-hint">Adicione titulares e reservas às equipes. Cada membro pode ser editado ou excluído depois.</p>' : ''}${isDistance ? '<p class="inline-edit-hint">Informe origem, destino e, se necessário, uma ou mais paradas separadas por ponto e vírgula. O mapa gratuito calcula os quilômetros e o tempo estimado.</p>' : ''}<div class="table-scroll"><table class="data-table module-data-table"><thead><tr>${spec.columns.map(col => `<th>${col[1]}</th>`).join('')}<th>Ações</th></tr></thead><tbody>${rows.map((row, index) => `<tr>${spec.columns.map(col => `<td>${id === 'parameters' && col[0] === 'value' ? `<input class="inline-parameter-value" data-parameter-index="${index}" aria-label="Valor de ${esc(row.name)}" value="${esc(row.value)}" />` : col[0] === 'status' || col[0] === 'accountStatus' ? `<span class="status-chip ${String(row[col[0]]).toLowerCase().includes('pend') || String(row[col[0]]).toLowerCase().includes('atras') ? 'warning-chip' : ''}">${esc(cellValue(row[col[0]], col[0]))}</span>` : esc(cellValue(row[col[0]], col[0]))}</td>`).join('')}<td class="row-actions">${actionButtons(id, row, index)}</td></tr>`).join('') || `<tr><td colspan="${spec.columns.length + 1}">Nenhum registo. Use o formulário para adicionar.</td></tr>`}</tbody></table></div></article><article class="panel module-form" id="moduleFormPanel"><div class="panel-heading"><div><h2>${isComposition ? 'Novo membro da equipe' : isDistance ? 'Calcular distância no mapa gratuito' : 'Novo registo'}</h2><p>Os campos ficam guardados neste navegador.</p></div><span class="file-icon">＋</span></div>${isDistance ? '<div class="distance-map-shell"><div class="map-panel-heading"><strong>Mapa da rota</strong><span>OpenStreetMap · OSRM</span></div><div class="distance-map" id="distanceMap" role="img" aria-label="Mapa gratuito da rota"></div><p class="map-attribution">© OpenStreetMap contributors · rotas OSRM</p></div>' : ''}<form class="generic-form" id="genericForm" data-module="${id}">${spec.fields.map(field => genericField(id, field)).join('')}<div class="form-actions"><span class="review-note">${isComposition ? 'Titulares e reservas podem ser editados depois.' : isDistance ? 'Calcule, revise o resultado e depois guarde o percurso.' : 'Campos podem ser editados depois no fluxo.'}</span><div class="form-button-row"><button class="button secondary" id="cancelGenericEdit" type="button" hidden>Cancelar</button>${isDistance ? '<button class="button secondary" id="calculateDistance" type="button">Calcular no mapa gratuito</button>' : ''}<button class="button primary" type="submit">${isComposition ? 'Adicionar membro' : isDistance ? 'Guardar distância' : 'Adicionar registo'}</button></div></div></form></article></div>`; bindGeneric(id); }
function actionButtons(id, row, index) { const edit = `<button class="mini-action" data-row-action="edit-row" data-index="${index}">Editar</button>`; const remove = `<button class="mini-action danger-action" data-row-action="delete-row" data-index="${index}">Excluir</button>`; if (id === 'changes' && row.status === 'Pendente') return `<div class="row-action-stack"><button class="mini-action" data-row-action="approve-change" data-index="${index}">Aprovar</button>${edit}${remove}</div>`; if (id === 'purchases' && row.status === 'Aguardando aprovação') return `<div class="row-action-stack"><button class="mini-action" data-row-action="approve-purchase" data-index="${index}">Aprovar</button>${edit}${remove}</div>`; if (id === 'fleet' && row.status !== 'Em dia') return `<div class="row-action-stack"><button class="mini-action" data-row-action="mark-fleet" data-index="${index}">Marcar em dia</button>${edit}${remove}</div>`; return `<div class="row-action-stack">${edit}${remove}</div>`; }
function bindGeneric(id) { const form = byId('genericForm'); const submit = form?.querySelector('button[type="submit"]'); const cancel = byId('cancelGenericEdit'); form?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(form).entries()); const spec = specs[id]; spec.fields.forEach(field => { if (field[2] === 'number' && data[field[0]] !== '') data[field[0]] = Number(String(data[field[0]]).replace(',', '.')); }); const key = defFor(id).stateKey; const editIndex = form.dataset.editIndex; let resultMessage = 'Registo adicionado ao módulo.'; if (editIndex !== undefined && editIndex !== '') { state[key][Number(editIndex)] = { ...state[key][Number(editIndex)], ...data }; resultMessage = 'Registo atualizado.'; } else if (id === 'composition') { const names = String(data.employee || '').split(/[\r\n;]+/).map(name => name.trim()).filter(Boolean); if (!names.length) { toast('Informe pelo menos um nome.'); return; } const normalizeName = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase(); let added = 0; let duplicates = 0; names.forEach(name => { const exists = state[key].some(row => normalizeName(row.team) === normalizeName(data.team) && normalizeName(row.employee) === normalizeName(name)); if (exists) { duplicates += 1; return; } state[key].push({ ...data, employee: name }); added += 1; }); if (!added) { toast('Esses nomes já estão cadastrados nessa equipe.'); return; } resultMessage = String(added) + ' membro(s) adicionado(s)' + (duplicates ? '; ' + String(duplicates) + ' duplicado(s) ignorado(s).' : ' à equipe.'); } else { state[key].push(data); } persist(); renderAll(); switchModule(id); toast(resultMessage); }); cancel?.addEventListener('click', () => resetGenericForm()); if (id === 'distances') { setupDistanceMap(); byId('calculateDistance')?.addEventListener('click', calculateDistanceWithOpenStreetMap); } byId('moduleHost').querySelectorAll('[data-parameter-index]').forEach(input => input.addEventListener('change', () => { const index = Number(input.dataset.parameterIndex); const value = input.value.trim(); if (!Number.isInteger(index) || !state.parameters[index] || !value) return; state.parameters[index].value = value; persist(); toast('Valor do parâmetro atualizado.'); })); byId('moduleExport')?.addEventListener('click', () => downloadWorkbook(`PEMx-RNA_${id}`)); document.querySelector('[data-scroll-form]')?.addEventListener('click', () => byId('moduleFormPanel')?.scrollIntoView({ behavior: 'smooth', block: 'center' })); byId('moduleHost').querySelectorAll('[data-row-action]').forEach(button => button.addEventListener('click', () => handleRowAction(id, Number(button.dataset.index), button.dataset.rowAction))); }
function setupDistanceMap() { const element = byId('distanceMap'); if (!element || !window.L) return; if (distanceMap && distanceMapElement === element) { window.setTimeout(() => distanceMap.invalidateSize(), 0); return; } if (distanceMap) distanceMap.remove(); distanceMapElement = element; distanceMap = window.L.map(element, { zoomControl: true, scrollWheelZoom: false }).setView([-12.5, 17.5], 5); window.L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 18, attribution: '&copy; OpenStreetMap contributors' }).addTo(distanceMap); distanceMarkersLayer = window.L.layerGroup().addTo(distanceMap); window.setTimeout(() => distanceMap.invalidateSize(), 0); }
function distanceRouteKey(route) { const mode = String(route.mode || '').toLowerCase(); return JSON.stringify([String(route.origin || '').trim().toLowerCase(), String(route.stop || '').trim().toLowerCase(), String(route.destination || '').trim().toLowerCase(), /a[eé]reo/.test(mode) ? 'air' : 'road']); }
function renderDistanceMap(result, mode = '') { setupDistanceMap(); if (!distanceMap || !result?.geometry?.coordinates?.length) return; distanceRouteLayer?.remove(); distanceMarkersLayer?.clearLayers(); const isAir = /a[eé]reo/i.test(String(mode)); const path = result.geometry.coordinates.map(([lon, lat]) => [lat, lon]); distanceRouteLayer = window.L.polyline(path, { color: isAir ? '#d58a22' : '#1d76d2', weight: 5, opacity: 0.9, dashArray: isAir ? '8 8' : null }).addTo(distanceMap); (result.points || []).forEach((point, index) => window.L.marker([point.lat, point.lon]).bindPopup(`${index === 0 ? 'Origem' : index === result.points.length - 1 ? 'Destino' : `Parada ${index}`}<br>${esc(point.query || point.name)}`).addTo(distanceMarkersLayer)); distanceMap.fitBounds(distanceRouteLayer.getBounds(), { padding: [24, 24] }); }
async function selectDistanceRoute(index) { const route = state.distances[index]; if (!route?.origin || !route?.destination) return; selectedDistanceKey = distanceRouteKey(route); const requestId = ++distanceSelectionRequest; byId('moduleHost').querySelectorAll('.distance-select-row').forEach(row => { const selected = Number(row.dataset.distanceIndex) === index; row.classList.toggle('selected-distance-row', selected); row.setAttribute('aria-selected', String(selected)); }); setupDistanceMap(); if (!distanceMap) return; const mapStatus = byId('moduleHost').querySelector('.map-panel-heading span'); const isAir = /a[eé]reo/i.test(String(route.mode || '')); if (mapStatus) mapStatus.textContent = 'A carregar percurso…'; distanceRouteLayer?.remove(); distanceRouteLayer = null; distanceMarkersLayer?.clearLayers(); try { let result = distanceRouteCache.get(selectedDistanceKey); if (!result) { const params = new URLSearchParams({ origin: route.origin, destination: route.destination }); String(route.stop || '').split(/[;\n]/).map(value => value.trim()).filter(Boolean).forEach(stop => params.append('stop', stop)); if (isAir) params.set('mode', 'air'); const response = await fetch(`${distanceApiBase}/api/distance?${params.toString()}`); result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(result.error || 'Não foi possível localizar este percurso no mapa.'); distanceRouteCache.set(selectedDistanceKey, result); } if (requestId !== distanceSelectionRequest || byId('genericForm')?.dataset.module !== 'distances') return; renderDistanceMap(result, route.mode); if (mapStatus) mapStatus.textContent = isAir ? 'Aéreo · linha direta aproximada' : 'OpenStreetMap · OSRM'; if (window.matchMedia('(max-width: 900px)').matches) distanceMapElement?.scrollIntoView({ behavior: 'smooth', block: 'center' }); toast(`Percurso ${route.origin} → ${route.destination} selecionado no mapa.`); } catch (error) { if (requestId !== distanceSelectionRequest) return; if (mapStatus) mapStatus.textContent = 'Percurso indisponível'; toast(error.message || 'Não foi possível mostrar este percurso.'); } }
async function calculateDistanceWithOpenStreetMap() { const form = byId('genericForm'); const origin = String(form?.elements.namedItem('origin')?.value || '').trim(); const destination = String(form?.elements.namedItem('destination')?.value || '').trim(); const stopText = String(form?.elements.namedItem('stop')?.value || '').trim(); const button = byId('calculateDistance'); if (!origin || !destination) { toast('Informe a origem e o destino antes de calcular.'); return; } const params = new URLSearchParams({ origin, destination }); stopText.split(/[;\n]/).map(value => value.trim()).filter(Boolean).forEach(stop => params.append('stop', stop)); if (button) { button.disabled = true; button.textContent = 'A calcular…'; } try { const response = await fetch(`${distanceApiBase}/api/distance?${params.toString()}`); const result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(result.error || 'Não foi possível calcular a distância.'); const km = form.elements.namedItem('km'); const mode = form.elements.namedItem('mode'); if (km) km.value = result.distanceKm; if (mode) mode.value = `OpenStreetMap · ${result.durationText}`; renderDistanceMap(result); toast(`Distância calculada: ${result.distanceKm} km. Revise e guarde o percurso.`); } catch (error) { toast(error.message || 'Não foi possível calcular a rota gratuita.'); } finally { if (button) { button.disabled = false; button.textContent = 'Calcular no mapa gratuito'; } } }
function populateGenericForm(id, index) { const form = byId('genericForm'); const row = rowsFor(id)[index]; if (!form || !row) return; form.dataset.editIndex = String(index); specs[id].fields.forEach(field => { const input = form.elements.namedItem(field[0]); if (input) input.value = row[field[0]] ?? ''; }); const title = byId('moduleFormPanel')?.querySelector('h2'); const submit = form.querySelector('button[type="submit"]'); const cancel = byId('cancelGenericEdit'); if (title) title.textContent = 'Editar registo'; if (submit) submit.textContent = 'Guardar alterações'; if (cancel) cancel.hidden = false; byId('moduleFormPanel')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); }
function resetGenericForm() { const form = byId('genericForm'); if (!form) return; form.reset(); delete form.dataset.editIndex; const title = byId('moduleFormPanel')?.querySelector('h2'); const submit = form.querySelector('button[type="submit"]'); const cancel = byId('cancelGenericEdit'); if (title) title.textContent = 'Novo registo'; if (submit) submit.textContent = 'Adicionar registo'; if (cancel) cancel.hidden = true; }
function handleRowAction(id, index, action) { if (action === 'edit-row') { populateGenericForm(id, index); return; } if (action === 'delete-row') { const key = defFor(id)?.stateKey; const record = key ? state[key]?.[index] : null; const label = record?.id || record?.name || record?.vehicle || record?.beneficiary || record?.description || 'selecionado'; if (!key || !record || !window.confirm(`Excluir o registo ${label}?`)) return; state[key].splice(index, 1); persist(); renderAll(); switchModule(id); toast('Registo excluído.'); return; } if (action === 'approve-change') { state.changes[index].status = 'Aprovada'; toast(`${state.changes[index].id} aprovada. Rotas e orçamento podem ser atualizados.`); } else if (action === 'approve-purchase') { state.purchases[index].status = 'Aprovada'; toast(`${state.purchases[index].id} aprovada para compra.`); } else if (action === 'mark-fleet') { state.fleet[index].status = 'Em dia'; toast(`${state.fleet[index].vehicle} marcada como em dia.`); } persist(); renderAll(); switchModule(id); }

function renderAccounting() { const t = totals(); byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">MÓDULO ADMINISTRATIVO</div><h1>Prestação de Contas</h1><p>Combustível e outras despesas pagas com o adiantamento. Importe o comprovativo e confirme os dados.</p></div><div class="heading-actions"><button class="button secondary" id="accountingExport"><span>↓</span> Exportar módulo</button><span class="admin-badge">${state.expenses.length} lançamentos</span></div></div><div class="expenses-layout"><article class="panel import-panel"><div class="panel-heading"><div><h2>Importar comprovativo</h2><p>Nota fiscal, fatura, recibo ou comprovativo em imagem/PDF.</p></div><span class="ai-pill"><span class="pulse"></span> OCR assistido</span></div><label class="upload-zone" id="dropZone" for="receiptFile"><input type="file" id="receiptFile" accept="image/*,.pdf,application/pdf" /><span class="upload-icon">↑</span><strong>Arraste o comprovativo para aqui</strong><span>ou clique para escolher · PNG, JPG ou PDF</span><small>Os campos extraídos são sempre revistos antes de gravar.</small></label><div class="extraction-state" id="extractionState"><span class="state-icon">✦</span><div><strong>Aguardando documento</strong><span>O sistema preencherá os campos quando fizer a leitura.</span></div></div><div class="manual-divider"><span>lançamento manual ou revisão do OCR</span></div><form class="expense-form" id="expenseForm"><div class="form-row two"><label>Equipe<select id="expenseTeam"><option>EQ-01</option><option>EQ-02</option><option>EQ-03</option></select></label><label>Data<input id="expenseDate" type="date" value="2026-11-08" required /></label></div><div class="form-row two"><label>Tipo de despesa<select id="expenseType"><option>Combustível</option><option>Portagem / estacionamento</option><option>Táxi / transporte local</option><option>Material / consumíveis</option><option>Outra</option></select></label><label>Valor (AOA)<input id="expenseAmount" inputmode="decimal" placeholder="0" required /></label></div><div class="form-row two"><label>Fornecedor / posto<input id="expenseSupplier" placeholder="Ex.: Sonangol" /></label><label>Nº fatura / recibo<input id="expenseInvoice" placeholder="Ex.: FT A/1001" /></label></div><label>Descrição<input id="expenseDescription" placeholder="Ex.: Gasóleo Luanda–Benguela" /></label><div class="form-row two"><label>Comprovativo anexado<select id="expenseAttachment"><option>Sim</option><option>Não</option></select></label><label>Viatura / observação<input id="expenseNote" placeholder="Ex.: CAM-02" /></label></div><div class="form-actions"><span class="review-note">✦ Campos extraídos ficam editáveis.</span><button type="submit" class="button primary"><span>＋</span> Gravar lançamento</button></div></form></article><article class="panel expense-ledger"><div class="panel-heading"><div><h2>Lançamentos recentes</h2><p>${state.expenses.length} registos · total comprovado ${money(t.expenses)}</p></div><span class="panel-tag">AOA</span></div><div class="table-scroll"><table class="data-table ledger-table"><thead><tr><th>Equipe / data</th><th>Natureza</th><th>Fornecedor</th><th class="align-right">Valor</th><th>Estado</th><th>Ações</th></tr></thead><tbody>${state.expenses.map((item, index) => ({ item, index })).reverse().map(({ item, index }) => `<tr><td><div class="ledger-team"><strong>${esc(item.team)}</strong><span>${shortDate(item.date)} · ${esc(item.description)}</span></div></td><td>${esc(item.type)}</td><td>${esc(item.supplier || '—')}</td><td class="align-right"><strong>${money(item.amount)}</strong></td><td><span class="status-chip">${esc(item.status || 'Para validar')}</span></td><td class="row-actions"><button class="mini-action danger-action" data-row-action="delete-row" data-index="${index}">Excluir</button></td></tr>`).join('')}</tbody></table></div><div class="ledger-footer"><span>Valor total lançado</span><strong>${money(t.expenses)}</strong></div></article></div>`; bindAccounting(); }
function bindAccounting() { byId('accountingExport')?.addEventListener('click', () => downloadWorkbook('Prestacao_Contas')); const dropZone = byId('dropZone'); const fileInput = byId('receiptFile'); dropZone?.addEventListener('dragover', event => { event.preventDefault(); dropZone.classList.add('dragover'); }); dropZone?.addEventListener('dragleave', () => dropZone.classList.remove('dragover')); dropZone?.addEventListener('drop', event => { event.preventDefault(); dropZone.classList.remove('dragover'); if (event.dataTransfer.files[0]) processReceipt(event.dataTransfer.files[0]); }); fileInput?.addEventListener('change', event => { if (event.target.files[0]) processReceipt(event.target.files[0]); }); byId('expenseForm')?.addEventListener('submit', event => { event.preventDefault(); const amount = Number(byId('expenseAmount').value.replace(/[^0-9,.-]/g, '').replace(',', '.')) || 0; if (!amount) return toast('Informe um valor válido antes de gravar.'); state.expenses.push({ id: `EXP-${String(state.expenses.length + 1).padStart(3, '0')}`, team: byId('expenseTeam').value, date: byId('expenseDate').value, type: byId('expenseType').value, description: byId('expenseDescription').value || 'Despesa extra', supplier: byId('expenseSupplier').value, invoice: byId('expenseInvoice').value, amount, attachment: byId('expenseAttachment').value, attachmentName: lastExtractedFile, note: byId('expenseNote').value, status: byId('expenseAttachment').value === 'Sim' ? 'Validado' : 'Para validar' }); persist(); lastExtractedFile = ''; renderAll(); switchModule('accounting'); toast('Lançamento gravado na prestação de contas.'); }); byId('moduleHost').querySelectorAll('[data-row-action]').forEach(button => button.addEventListener('click', () => handleRowAction('accounting', Number(button.dataset.index), button.dataset.rowAction))); }
async function processReceipt(file) { lastExtractedFile = file.name; const stateEl = byId('extractionState'); stateEl.innerHTML = `<span class="state-icon">◌</span><div><strong>A ler ${esc(file.name)}</strong><span>A extração pode levar alguns segundos. Confirme todos os campos.</span></div>`; let text = ''; try { text = await extractText(file); } catch (error) { console.warn(error); } fillExpenseFields(parseReceiptText(text, file.name)); stateEl.innerHTML = `<span class="state-icon">✓</span><div><strong>${text ? 'Dados extraídos — revisão necessária' : 'Documento carregado — preencha os campos'}</strong><span>${text ? 'Confira valor, fornecedor e número do documento antes de gravar.' : 'OCR indisponível neste navegador. O arquivo ficou associado.'}</span></div>`; toast(text ? 'Comprovativo lido. Revise os campos extraídos.' : 'Comprovativo carregado. Preencha os campos.'); }
async function extractText(file) { if (file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')) return extractPdfText(file); if (!window.Tesseract) await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js'); if (!window.Tesseract) return ''; const result = await window.Tesseract.recognize(file, 'por+eng', { logger: data => { if (data.status === 'recognizing text' && byId('extractionState')) byId('extractionState').querySelector('strong').textContent = `A ler comprovativo · ${Math.round(data.progress * 100)}%`; } }); return result.data.text || ''; }
async function extractPdfText(file) { if (!window.pdfjsLib) await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js'); if (!window.pdfjsLib) return ''; window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; const pdf = await window.pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise; let extracted = ''; for (let pageNumber = 1; pageNumber <= Math.min(pdf.numPages, 3); pageNumber += 1) { const page = await pdf.getPage(pageNumber); const content = await page.getTextContent(); extracted += content.items.map(item => item.str || '').join(' ') + '\n'; } return extracted.trim(); }
function loadScript(src) { return new Promise(resolve => { const script = document.createElement('script'); script.src = src; script.onload = resolve; script.onerror = resolve; document.head.appendChild(script); }); }

function renderAccessControl() { if (currentUser?.profileId !== 'administrador') { toast('Somente o administrador pode gerir perfis e acessos.'); return switchModule('summary'); } const managedModules = moduleDefs.filter(item => item.id !== 'summary'); const profileRows = state.profiles.map(profile => `<tr><th><strong>${esc(profile.name)}</strong><small>${esc(profile.description)}</small></th>${managedModules.map(item => `<td><label class="permission-toggle"><input type="checkbox" data-profile-id="${esc(profile.id)}" data-permission="${esc(item.id)}" ${profile.permissions.includes(item.id) ? 'checked' : ''} ${profile.id === 'administrador' && item.id === 'access' ? 'disabled' : ''} /><span>${profile.permissions.includes(item.id) ? '✓' : '—'}</span></label></td>`).join('')}</tr>`).join(''); const userRows = state.users.map(user => `<tr><td><strong>${esc(user.name)}</strong><small>${esc(user.username)} · ${user.active ? 'Ativo' : 'Inativo'}</small></td><td><input class="user-email-input" data-user-id="${esc(user.id)}" type="email" value="${esc(user.email || '')}" placeholder="email@empresa.com" aria-label="E-mail de ${esc(user.name)}" /></td><td><select class="user-profile-select" data-user-id="${esc(user.id)}">${state.profiles.map(profile => `<option value="${esc(profile.id)}" ${profile.id === user.profileId ? 'selected' : ''}>${esc(profile.name)}</option>`).join('')}</select></td><td><span class="status-chip ${user.active ? '' : 'warning-chip'}">${user.active ? 'Ativo' : 'Inativo'}</span></td><td><button class="mini-action danger-action" data-user-action="delete" data-user-id="${esc(user.id)}" ${user.id === currentUser.id ? 'disabled' : ''}>Excluir</button></td></tr>`).join(''); byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">ADMINISTRADOR</div><h1>Perfis e acessos</h1><p>Defina o que cada perfil pode abrir e associe cada usuário ao seu perfil.</p></div><span class="admin-badge">${state.users.length} usuários</span></div><div class="access-layout"><article class="panel access-panel"><div class="panel-heading"><div><h2>Matriz de permissões</h2><p>Marque os módulos permitidos para cada perfil.</p></div><span class="panel-tag">Editável</span></div><div class="access-matrix-scroll"><table class="access-matrix"><thead><tr><th>Perfil</th>${managedModules.map(item => `<th title="${esc(item.label)}">${item.icon}<span>${esc(item.label)}</span></th>`).join('')}</tr></thead><tbody>${profileRows}</tbody></table></div></article><article class="panel access-users-panel"><div class="panel-heading"><div><h2>Usuários e perfis</h2><p>Altere o perfil e o e-mail de cada usuário.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Estado</th><th>Ações</th></tr></thead><tbody>${userRows || '<tr><td colspan="5">Nenhum usuário cadastrado.</td></tr>'}</tbody></table></div><form class="access-user-form" id="accessUserForm"><h3>Adicionar usuário</h3><div class="form-row two"><label>Nome<input name="name" required placeholder="Nome completo" /></label><label>Login<input name="username" required placeholder="usuario" /></label></div><div class="form-row two"><label>E-mail<input name="email" type="email" placeholder="email@empresa.com" /></label><label>Senha inicial<input name="password" required type="password" placeholder="Senha" /></label></div><label>Perfil<select name="profileId">${state.profiles.map(profile => `<option value="${esc(profile.id)}">${esc(profile.name)}</option>`).join('')}</select></label><button class="button primary" type="submit">＋ Criar usuário</button></form></article></div>`; bindAccessControl(); }

function bindAccessControl() { byId('moduleHost').querySelectorAll('[data-profile-id]').forEach(input => input.addEventListener('change', () => { const profile = state.profiles.find(item => item.id === input.dataset.profileId); if (!profile) return; if (input.dataset.permission === 'access' && profile.id === 'administrador') { input.checked = true; return; } profile.permissions = input.checked ? [...new Set([...profile.permissions, input.dataset.permission])] : profile.permissions.filter(permission => permission !== input.dataset.permission); persist(); input.nextElementSibling.textContent = input.checked ? '✓' : '—'; toast(`Permissão de ${profile.name} atualizada.`); })); byId('moduleHost').querySelectorAll('.user-email-input').forEach(input => input.addEventListener('change', () => { const user = state.users.find(item => item.id === input.dataset.userId); if (!user) return; user.email = input.value.trim(); persist(); toast(`E-mail de ${user.name} atualizado.`); })); byId('moduleHost').querySelectorAll('.user-profile-select').forEach(select => select.addEventListener('change', () => { const user = state.users.find(item => item.id === select.dataset.userId); if (!user) return; user.profileId = select.value; persist(); if (user.id === currentUser.id) updateCurrentUserUi(); toast(`Perfil de ${user.name} atualizado.`); })); byId('moduleHost').querySelectorAll('[data-user-action="delete"]').forEach(button => button.addEventListener('click', () => { const user = state.users.find(item => item.id === button.dataset.userId); if (!user || user.id === currentUser.id || !window.confirm(`Excluir o usuário ${user.name}?`)) return; state.users = state.users.filter(item => item.id !== user.id); persist(); renderAccessControl(); toast('Usuário excluído.'); })); byId('accessUserForm')?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget).entries()); if (state.users.some(user => user.username.toLowerCase() === String(data.username).trim().toLowerCase())) return toast('Este login já está cadastrado.'); state.users.push({ id: `USR-${String(Date.now()).slice(-5)}`, name: String(data.name).trim(), username: String(data.username).trim(), email: String(data.email || '').trim(), password: String(data.password), profileId: data.profileId, active: true }); persist(); renderAccessControl(); toast('Usuário criado.'); }); }
function parseReceiptText(text, filename) { const raw = text.trim(); const normalized = raw.replace(/\s+/g, ' ').trim(); const amountMatch = normalized.match(/(?:AOA|KZ|Kz|Total|TOTAL)[^\d]{0,20}([\d .]+[,\.]\d{2}|[\d .]{3,})/i); const invoiceMatch = normalized.match(/(?:fatura|factura|recibo|n[ºo°]?)[^A-Z0-9]{0,10}([A-Z0-9][A-Z0-9/\- .]{3,})/i); const dateMatch = normalized.match(/(\d{1,2}[/.\-]\d{1,2}[/.\-]\d{2,4})/); const supplier = raw.split(/\n|\r/).map(x => x.trim()).find(x => x.length > 3 && !/fatura|factura|recibo|total|valor|data/i.test(x)) || ''; return { amount: amountMatch ? amountMatch[1].replace(/\s/g, '').replace(/\.(?=\d{3})/g, '').replace(',', '.') : '', invoice: invoiceMatch ? invoiceMatch[1].trim() : '', date: dateMatch ? normalizeDate(dateMatch[1]) : '', supplier: supplier.slice(0, 70), description: filename ? `Documento importado: ${filename}` : '' }; }
function normalizeDate(value) { const parts = value.split(/[/.\-]/); if (parts.length !== 3) return ''; const [d, m, y] = parts; return `${y.length === 2 ? '20' + y : y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`; }
function fillExpenseFields(parsed) { if (parsed.amount) byId('expenseAmount').value = parsed.amount; if (parsed.invoice) byId('expenseInvoice').value = parsed.invoice; if (parsed.date) byId('expenseDate').value = parsed.date; if (parsed.supplier) byId('expenseSupplier').value = parsed.supplier; if (parsed.description) byId('expenseDescription').value = parsed.description; }

function bindAccessControlImproved() { byId('moduleHost').querySelectorAll('[data-profile-id]').forEach(input => input.addEventListener('change', () => { const profile = state.profiles.find(item => item.id === input.dataset.profileId); if (!profile) return; if (input.dataset.permission === 'access' && profile.id === 'administrador') { input.checked = true; return; } profile.permissions = input.checked ? [...new Set([...profile.permissions, input.dataset.permission])] : profile.permissions.filter(permission => permission !== input.dataset.permission); persist(); input.nextElementSibling.textContent = input.checked ? '✓' : '—'; toast(`Permissão de ${profile.name} atualizada.`); })); byId('moduleHost').querySelectorAll('.user-email-input').forEach(input => { let timer = null; const saveEmail = () => { window.clearTimeout(timer); timer = window.setTimeout(() => { const user = state.users.find(item => item.id === input.dataset.userId); if (!user) return; const email = String(input.value || '').trim(); if (user.email === email) return; user.email = email; persist(); toast(`E-mail de ${user.name} atualizado.`); }, 250); }; input.addEventListener('input', saveEmail); input.addEventListener('change', saveEmail); input.addEventListener('blur', saveEmail); }); byId('moduleHost').querySelectorAll('.user-profile-select').forEach(select => select.addEventListener('change', () => { const user = state.users.find(item => item.id === select.dataset.userId); if (!user) return; user.profileId = select.value; persist(); if (user.id === currentUser.id) updateCurrentUserUi(); toast(`Perfil de ${user.name} atualizado.`); })); byId('moduleHost').querySelectorAll('[data-user-action="delete"]').forEach(button => button.addEventListener('click', () => { const user = state.users.find(item => item.id === button.dataset.userId); if (!user || user.id === currentUser.id || !window.confirm(`Excluir o usuário ${user.name}?`)) return; state.users = state.users.filter(item => item.id !== user.id); persist(); renderAccessControl(); toast('Usuário excluído.'); })); byId('accessUserForm')?.addEventListener('submit', event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget).entries()); if (state.users.some(user => user.username.toLowerCase() === String(data.username).trim().toLowerCase())) return toast('Este login já está cadastrado.'); state.users.push({ id: `USR-${String(Date.now()).slice(-5)}`, name: String(data.name).trim(), username: String(data.username).trim(), email: String(data.email || '').trim(), password: String(data.password), profileId: data.profileId, active: true }); persist(); renderAccessControl(); toast('Usuário criado.'); }); }
