function renderReports() { const t = totals(); byId('moduleHost').innerHTML = `<div class="page-heading compact-heading"><div><div class="kicker">ADMINISTRADOR</div><h1>Relatórios financeiros</h1><p>Exporte os demonstrativos financeiros em PDF e Excel com todos os módulos operacionais.</p></div><span class="admin-badge">PDF + Excel</span></div><div class="report-layout"><article class="panel report-config"><div class="panel-heading"><div><h2>Gerar relatório completo</h2><p>O arquivo inclui Resumo, Instruções, Parâmetros, fluxo de caixa por etapas, rotas, frota, pagamentos e prestação.</p></div><span class="file-icon">PDF</span></div><div class="report-fields"><label>Período<select><option>Novembro 2026</option><option>Todos os períodos</option></select></label><label>Escopo<select><option>Todos os módulos</option><option>Somente financeiros</option><option>Somente operação</option></select></label><label>Formato<select disabled><option>PDF + Excel</option></select></label></div><div class="report-includes"><span class="include-title">Demonstrativos incluídos</span><div class="include-grid"><span>✓ Resumo financeiro</span><span>✓ Orçamento por equipe</span><span>✓ Diárias e passagens</span><span>✓ Rotas e alterações</span><span>✓ Frota e quilometragem</span><span>✓ Compras e pagamentos</span><span>✓ Prestação de contas</span><span>✓ Fluxo de caixa por etapa</span><span>✓ Parâmetros e notas</span></div></div><div class="report-actions"><button class="button secondary" id="generateReportPdf"><span>↓</span> Baixar PDF</button><button class="button primary" id="generateReportExcel"><span>↓</span> Baixar Excel</button></div><div class="export-note">A exportação é gerada localmente com os dados deste navegador.</div></article><article class="panel report-history"><div class="panel-heading"><div><h2>Prévia do resumo</h2><p>Valores que serão enviados para PDF e Excel.</p></div><span class="panel-tag">NOV 2026</span></div><div class="preview-grid"><div><span>Total previsto</span><strong>${money(state.budget.total)}</strong></div><div><span>Subtotal previsto</span><strong>${money(state.budget.subtotal)}</strong></div><div><span>Realizado</span><strong>${money(t.realized)}</strong></div><div><span>A pagar</span><strong>${money(t.balance)}</strong></div></div><div class="history-list"><div class="empty-history"><span>↗</span><div><strong>O próximo download ficará disponível no histórico</strong><span>Os registos ficam guardados apenas no seu dispositivo.</span></div></div></div></article></div>`; byId('generateReportPdf').addEventListener('click', () => downloadPdf('PEMx-RNA_Relatorio_Completo')); byId('generateReportExcel').addEventListener('click', () => downloadWorkbook('PEMx-RNA_Relatorio_Completo')); }

function moduleRowsForExport(id) { if (id === 'instructions') return [['Tópico', 'Descrição'], ['Fluxo', 'Cadastre parâmetros, pessoas e equipes antes de rotas.'], ['Regras', 'Apenas alterações aprovadas atualizam o planeamento.'], ['Prestação', 'Combustível e outras despesas pagas com adiantamento.']]; if (id === 'cashflow') return cashFlowRows(); const spec = specs[id]; if (!spec) return []; return [spec.columns.map(col => col[1]), ...rowsFor(id).map(row => spec.columns.map(col => row[col[0]] ?? ''))]; }
function workbookSheets() { const t = totals(); const sheets = { 'Resumo Financeiro': [['Demonstrativo', 'Valor (AOA)'], ['Total previsto', state.budget.total], ['Previsto por etapas', cashFlowDataset().metrics.distributed], ['Pagamentos registados', cashFlowDataset().metrics.paid], ['Subtotal previsto', state.budget.subtotal], ['Contingência financeira', state.budget.contingency], ['Reserva de pessoal', state.budget.personnelReserve], ['Realizado', t.realized], ['A pagar / regularizar', t.balance], ['Economia por rotas diretas', state.budget.savings]] }; moduleDefs.filter(item => item.id !== 'summary' && item.id !== 'reports').forEach(item => { const safeName = item.label.replace(/[\\/*?:\[\]]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 31); sheets[safeName] = moduleRowsForExport(item.id); }); return sheets; }
function downloadPdf(prefix) { const JsPDF = window.jspdf?.jsPDF; if (!JsPDF) { toast('Biblioteca PDF ainda não carregada.'); return; } const doc = new JsPDF({ orientation: 'landscape', unit: 'pt', format: 'a4' }); const t = totals(); doc.setFont('helvetica', 'bold'); doc.setFontSize(18); doc.text('FlowRoute Finance', 40, 40); doc.setFontSize(12); doc.text('Relatório financeiro completo', 40, 60); doc.setFont('helvetica', 'normal'); doc.setFontSize(9); doc.text(`Gerado em ${new Date().toLocaleString('pt-AO')}`, 40, 76); const summary = [['Total previsto', money(state.budget.total)], ['Previsto por etapas', money(cashFlowDataset().metrics.distributed)], ['Pagamentos registados', money(cashFlowDataset().metrics.paid)], ['Subtotal previsto', money(state.budget.subtotal)], ['Contingência financeira', money(state.budget.contingency)], ['Reserva de pessoal', money(state.budget.personnelReserve)], ['Realizado', money(t.realized)], ['A pagar / regularizar', money(t.balance)], ['Economia por rotas diretas', money(state.budget.savings)]]; doc.autoTable({ startY: 92, head: [['Demonstrativo', 'Valor']], body: summary, theme: 'grid', styles: { fontSize: 8 } }); let y = doc.lastAutoTable.finalY + 24; Object.entries(workbookSheets()).forEach(([name, rows]) => { if (name === 'Resumo Financeiro' || !rows.length) return; if (y > 500) { doc.addPage(); y = 40; } doc.setFont('helvetica', 'bold'); doc.setFontSize(11); doc.text(name, 40, y); const header = rows[0].map(value => String(value ?? '')); const body = rows.slice(1).slice(0, 60).map(row => row.map(value => String(value ?? ''))); doc.autoTable({ startY: y + 8, head: [header], body, theme: 'grid', styles: { fontSize: 7 }, margin: { left: 40, right: 40 } }); y = doc.lastAutoTable.finalY + 20; }); doc.save(`${prefix}_${new Date().toISOString().slice(0, 10)}.pdf`); toast('Relatório PDF gerado.'); }
function downloadWorkbook(prefix) { const sheets = workbookSheets(); if (window.XLSX) { const workbook = window.XLSX.utils.book_new(); Object.entries(sheets).forEach(([name, rows]) => window.XLSX.utils.book_append_sheet(workbook, window.XLSX.utils.aoa_to_sheet(rows), name.slice(0, 31))); window.XLSX.writeFile(workbook, `${prefix}_${new Date().toISOString().slice(0, 10)}.xlsx`); toast(`Relatório Excel gerado com ${Object.keys(sheets).length} abas.`); return; } const xml = `<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"></Workbook>`; const blob = new Blob([xml], { type: 'application/vnd.ms-excel' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${prefix}_${new Date().toISOString().slice(0, 10)}.xls`; anchor.click(); URL.revokeObjectURL(url); toast('Relatório Excel compatível gerado.'); }

let deferredInstallPrompt = null;
function bindPwa() { if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw.js').catch(() => {}); window.addEventListener('beforeinstallprompt', event => { event.preventDefault(); deferredInstallPrompt = event; const button = byId('installButton'); if (button) button.hidden = false; }); window.addEventListener('appinstalled', () => { deferredInstallPrompt = null; const button = byId('installButton'); if (button) button.hidden = true; toast('FlowRoute instalado como aplicativo.'); }); byId('installButton')?.addEventListener('click', async () => { if (!deferredInstallPrompt) { toast('A instalação ficará disponível no menu do navegador.'); return; } deferredInstallPrompt.prompt(); const choice = await deferredInstallPrompt.userChoice; if (choice.outcome === 'accepted') toast('Instalação do FlowRoute iniciada.'); deferredInstallPrompt = null; byId('installButton').hidden = true; }); }

