renderGeneric = function(id) { renderGenericWithDistanceSelection(id); if (id !== 'distances') return; const rows = byId('moduleHost').querySelectorAll('.module-data-table tbody tr'); rows.forEach((row, index) => { const route = state.distances[index]; if (!route) return; row.classList.add('distance-select-row'); row.dataset.distanceIndex = String(index); row.tabIndex = 0; row.setAttribute('aria-label', `Mostrar percurso ${route.origin} para ${route.destination} no mapa`); const selected = distanceRouteKey(route) === selectedDistanceKey; row.classList.toggle('selected-distance-row', selected); row.setAttribute('aria-selected', String(selected)); }); const hint = byId('moduleHost').querySelector('.module-table > .inline-edit-hint'); if (hint && !hint.textContent.includes('Clique num percurso')) hint.textContent += ' Clique num percurso para o exibir no mapa.'; const selectedIndex = state.distances.findIndex(route => distanceRouteKey(route) === selectedDistanceKey); if (selectedIndex >= 0) window.setTimeout(() => selectDistanceRoute(selectedIndex), 0); else if (selectedDistanceKey) selectedDistanceKey = ''; };
